1	const AGENT_URL = process.env.NEXT_PUBLIC_PRINT_AGENT_URL ?? "http://127.0.0.1:9123";
2	
3	export type PrintAgentResult =
4	  | { ok: true }
5	  | { ok: false; reason: "agent_unreachable" | "printer_unreachable"; error: string };
6	
7	// Called from the browser — the cashier's PC is on the same LAN as the
8	// printer, unlike the Vercel server, so this is the only place that can
9	// actually reach a printer at e.g. 192.168.1.50:9100. See print-agent/.
10	export async function printViaAgent(address: string, bytesBase64: string): Promise<PrintAgentResult> {
11	  const [ip, portStr] = address.split(":");
12	  const port = portStr ? Number(portStr) : 9100;
13	
14	  try {
15	    const res = await fetch(`${AGENT_URL}/print`, {
16	      method: "POST",
17	      headers: { "Content-Type": "application/json" },
18	      body: JSON.stringify({ ip, port, bytes: bytesBase64 }),
19	    });
20	    const data = (await res.json()) as { ok: boolean; error?: string };
21	    if (data.ok) return { ok: true };
22	    return { ok: false, reason: "printer_unreachable", error: data.error ?? "unknown_error" };
23	  } catch {
24	    // fetch throws on network failure — the agent isn't running or isn't reachable at all.
25	    return { ok: false, reason: "agent_unreachable", error: "print_agent_not_running" };
26	  }
27	}
